import{_ as a}from"./chunks/template-manager-prerequisite.CF8Q4kRA.js";import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Template Manager και προσχέδια καναλιών","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/template-manager.md","filePath":"el/websites/template-manager.md"}'),s={name:"el/websites/template-manager.md"};function i(n,e,m,p,h,d){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="template-manager-και-προσχεδια-καναλιων" tabindex="-1">Template Manager και προσχέδια καναλιών <a class="header-anchor" href="#template-manager-και-προσχεδια-καναλιων" aria-label="Permalink to &quot;Template Manager και προσχέδια καναλιών&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/template-manager-prerequisite.png"><img src="'+a+'" alt="Website &amp; Themes χωρίς κανάλι κρατήσεων: ο διαχειριστής θεμάτων απαιτεί κανάλι της εταιρείας. Το ανεξάρτητο Website Studio παραμένει προσβάσιμο. Εμφανίζεται η προϋπόθεση πρόσβασης, όχι ο πλήρης επεξεργαστής θεμάτων."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Website &amp; Themes χωρίς κανάλι κρατήσεων: ο διαχειριστής θεμάτων απαιτεί κανάλι της εταιρείας. Το ανεξάρτητο Website Studio παραμένει προσβάσιμο. Εμφανίζεται η προϋπόθεση πρόσβασης, όχι ο πλήρης επεξεργαστής θεμάτων.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><h2 id="σκοπος-και-προυποθεσεις" tabindex="-1">Σκοπός και προϋποθέσεις <a class="header-anchor" href="#σκοπος-και-προυποθεσεις" aria-label="Permalink to &quot;Σκοπός και προϋποθέσεις&quot;">​</a></h2><p>Διαχειριστείτε οπτικά πρότυπα για προεπισκόπηση storefront και ενσωματωμένου widget κράτησης. Απαιτούνται εξουσιοδοτημένη εταιρεία, κανάλι κρατήσεων και τα κατάλληλα δικαιώματα.</p><h2 id="ελεγχος-προτυπου" tabindex="-1">Έλεγχος προτύπου <a class="header-anchor" href="#ελεγχος-προτυπου" aria-label="Permalink to &quot;Έλεγχος προτύπου&quot;">​</a></h2><ol><li>Ανοίξτε <strong>Settings → Website &amp; Themes</strong> και επιλέξτε Theme &amp; Channel Manager.</li><li>Επιλέξτε εταιρεία και κανάλι κρατήσεων και εισαγάγετε επικυρωμένο <code>.tbtheme.json</code>.</li><li>Ελέγξτε <strong>Full Storefront</strong> και <strong>Embed Widget</strong> ανά συσκευή και γλώσσα.</li><li>Αποθηκεύστε προσχέδιο καναλιού όπου υποστηρίζεται και ελέγξτε την αναθεώρηση.</li></ol><h2 id="ορια-αποθηκευσης" tabindex="-1">Όρια αποθήκευσης <a class="header-anchor" href="#ορια-αποθηκευσης" aria-label="Permalink to &quot;Όρια αποθήκευσης&quot;">​</a></h2><p>Ο κώδικας αναφοράς περιλαμβάνει πλήρη βιβλιοθήκη προτύπων και λειτουργία συμβατότητας μέσω αναθεωρήσεων καναλιών. Η πλήρης αποθήκευση απαιτεί ξεχωριστά εγκεκριμένη αλλαγή σχήματος. Η έκδοση αναφοράς δεν αποδεικνύει ότι έχει ενεργοποιηθεί. Στη λειτουργία συμβατότητας, εγγραφές μόνο στη βιβλιοθήκη μπορεί να απορρίπτονται.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν απορριφθεί η αποθήκευση, διατηρήστε το εξαγόμενο πακέτο. Ζητήστε από εξουσιοδοτημένο διαχειριστή έλεγχο της λειτουργίας αποθήκευσης. Μην επαναλαμβάνετε άσκοπα εγγραφές. Η εμφάνιση εφεδρικού προτύπου δεν αποδεικνύει εφαρμογή του επιλεγμένου. Δείτε <a href="./publication-controls.html">ελέγχους δημοσίευσης</a>.</p>',15)])])}const _=t(s,[["render",i]]);export{u as __pageData,_ as default};
